                }
                if (prop.NameEquals("endTimeMs"u8))
                {
                    endTimeMs = prop.Value.GetInt64();
                    continue;
                }
                if (prop.NameEquals("width"u8))
                {
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        continue;
                    }
                    width = prop.Value.GetInt32();
                    continue;
                }
                if (prop.NameEquals("height"u8))
                {
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        continue;
